operation.query:
with CTE(TypeName, countValue) as (
select 'Minors (17 yers and under)', count(*) as CountValue from GBVMain where deleted = 0 and AgeOfSurvivor <= 17 union select 'Adults (18 and above)', count(*) as CountValue from GBVMain where deleted = 0 and AgeOfSurvivor > 17
) select typename as PropertyName, countValue as PropertyValue1, format( (convert(decimal, cte.countValue) / convert(int, (select sum(countValue) from cte)) ),'P') as PropertyValue2 from cte
